GimCorpus.put(441,0,[[2,4,"חטא ונודע לו. א\"א הא אפילו לר' יהושע:",1,0],[2,4,"כשאר חטאות הנאכלות. א\"א סיפא דתוספ' קשיא לי דקתני וחוזר ומביא חטאת על הידיעה ותשחט לשם מה שהיא ותאכל:",2,0],[8,3,"האוכל חתיכה וכו' עד הואיל ונקבע האיסור. א\"א לא ידעתי היאך נקבע האיסור בכאן אלא אם כן יאמר העד חתיכה של חלב שהיתה עם השומן אכלת והאחר יאמר לא אכל אלא השומן:",1,0],[9,3,"בן תשע שנים ויום אחד שבא על שפחה חרופה היא לוקה. א\"א אומר אני שזה שיבוש שהרי שנינו בשפחה אחד גדול ואחד קטן גדול נמי פטור וכ\"ש הקטן. ואם יאמר האיש נתלה באשה אבל לא האשה באיש מ\"מ מהיכא תיתי לחייב את הקטן על ידי האשה הא ודאי טעותא הוא:",1,0],[10,7,"מביאין קרבנן על שבועת העדות. א\"א אין המלך חייב בשמיעת קול ולא המשיח בטומאת מקדש וקדשיו:",1,0],[11,8,"היה טמא ואמרו שנים וכו' עד הרי אלו נאמנים. א\"א זו הסוגיא שלנו באה לדעת חכמים דאתו לה משום מגו אבל לדעת ר\"י דאתי לה משום דאדם נאמן על ידי עצמו יותר ממאה איש אפילו אמר לא נטמאתי מעולם דקא מכחיש להו במגע הטומאה הוא נאמן וקא פסק רב הלכה כר\"י ואמר רב יוסף אפילו ר' יהודה אלא בינו לבין עצמו פירוש שלא יאכל קדש בפני העדים שמעידין עליו ולא יגע בטהרות של אחרים:",1,0],[13,4,"הורו בית דין בחלב מן החלבים עד הרי אלו מצטרפין. א\"א בעיא ולא איפשיטא היא ולא בית דין מייתו ולא צבור מייתו:",1,0],[14,5,"ועשה על פיהם מאחר שידעו הרי זה פטור. א\"א דדוקא שעשה אחר שחטאו רוב הקהל על פיהם שכבר נתחייבו ב\"ד אבל אם עשה עד שלא חטאו רוב הקהל מביא חטאת יחיד שהרי פסק למעלה יחיד שעשה בהוראת ב\"ד חייב וכ\"ש כשעשה אחר שחזרו שהוא חייב:",1,0]]);
